/**
 * The GraphMentor AI seed curriculum.
 *
 * This single dataset drives:
 *   - `scripts/emit-cypher.ts`  -> neo4j/schema.cypher + neo4j/seed.cypher
 *   - the browser's local sample mode (clearly labelled, never presented as live)
 *   - every unit/integration test of the recommendation engine
 *
 * Authoring rules followed here:
 *   1. Nothing is invented to hit a count. Every career, skill, project and
 *      resource below is a real, commonly taught engineering topic; every
 *      resource URL is checked by `npm run verify:resources`.
 *   2. Access conditions are recorded honestly: "free-audit" is not "free".
 *   3. Safety: hardware projects that touch mains power, soldering, batteries or
 *      fasteners carry explicit safety notes, and dangerous instructions are
 *      deliberately absent.
 *   4. Time ranges are ranges, not promises.
 *
 * Identifier convention:  <prefix>:<kebab-case>   e.g. skill:circuit-analysis
 */
import type {
  KnowledgeDataset,
  SeedAssessment,
  SeedBranch,
  SeedCareer,
  SeedConcept,
  SeedEdge,
  SeedLanguage,
  SeedModule,
  SeedProject,
  SeedResource,
  SeedSkill,
  SeedSubject,
  SeedTool,
} from '../../../supabase/functions/_shared/core/dataset.ts'
import type { Difficulty } from '../../../supabase/functions/_shared/core/types.ts'
import resourceVerification from './resourceVerification.json'

/* ==========================================================================
 * Compact authoring helpers
 * ========================================================================== */

interface SkillInput {
  summary: string
  description: string
  practice?: string[]
  criteria?: string[]
  tags?: string[]
  selfReported?: boolean
  verification?: SeedSkill['verification']
}

const skill = (id: string, name: string, difficulty: Difficulty, hours: [number, number], input: SkillInput): SeedSkill => ({
  id,
  name,
  summary: input.summary,
  description: input.description,
  difficulty,
  estimatedHoursLow: hours[0],
  estimatedHoursHigh: hours[1],
  practice: input.practice ?? [
    `Write down ${name} in your own words, then apply it to one small problem.`,
    `Find a worked example and redo it without looking at the solution.`,
  ],
  completionCriteria: input.criteria ?? [
    `You can explain ${name} to another student without notes.`,
    `You used it once in an exercise you wrote yourself.`,
  ],
  mustBeSelfReported: input.selfReported ?? true,
  verification: input.verification ?? 'community',
  ...(input.tags ? { tags: input.tags } : {}),
})

interface ProjectInput {
  summary: string
  description: string
  objectives: string[]
  deliverables: string[]
  milestones: string[]
  testing: string[]
  extensions?: string[]
  safety?: string[]
  tools: string[]
  skillIds: string[]
  hours: [number, number]
  tags?: string[]
}

const project = (id: string, name: string, difficulty: Difficulty, input: ProjectInput): SeedProject => ({
  id,
  name,
  summary: input.summary,
  description: input.description,
  difficulty,
  objectives: input.objectives,
  skillIds: input.skillIds,
  tools: input.tools,
  deliverables: input.deliverables,
  milestones: input.milestones,
  testingIdeas: input.testing,
  extensions: input.extensions ?? [],
  safetyNotes: input.safety ?? [],
  estimatedHoursLow: input.hours[0],
  estimatedHoursHigh: input.hours[1],
  ...(input.tags ? { tags: input.tags } : {}),
})

interface ResourceInput {
  summary: string
  provider: string
  url: string
  format: SeedResource['format']
  difficulty: Difficulty
  accessModel: SeedResource['accessModel']
  accessNote: string
  language?: string
  verified?: string | null
  verification?: SeedResource['verification']
  tags?: string[]
  outcomes: string[]
  assumes: string
  /** Skills this material presumes you already have (ASSUMES edges). */
  assumesSkillIds: string[]
  limits: string
  commitment: string
  /** An honest estimate in hours, calibrated against the skill estimates. */
  estimatedHoursLow: number
  estimatedHoursHigh: number
}

/**
 * Link-check outcomes, written by `npm run verify:resources`.
 *
 * Only a link that actually answered (or redirected) when the command ran is
 * reported as verified, and the date the app shows is the date of that run. A
 * provider that blocked the checker stays `community`: better to say "could not
 * confirm" than to imply it was fine.
 */
const checkedLinks: Record<string, { outcome: string; checkedAt: string; url: string }> = resourceVerification

const resource = (id: string, name: string, input: ResourceInput): SeedResource => {
  const checked = checkedLinks[id]
  const reachable = checked?.outcome === 'ok' || checked?.outcome === 'redirected'
  return {
    id,
    name,
    summary: input.summary,
    provider: input.provider,
    url: input.url,
    format: input.format,
    difficulty: input.difficulty,
    language: input.language ?? 'en',
    accessModel: input.accessModel,
    accessNote: input.accessNote,
    outcomes: input.outcomes,
    assumes: input.assumes,
    limits: input.limits,
    commitment: input.commitment,
    estimatedHoursLow: input.estimatedHoursLow,
    estimatedHoursHigh: input.estimatedHoursHigh,
    lastVerified: input.verified ?? (reachable ? checked.checkedAt : null),
    verification: input.verification ?? (reachable ? 'verified' : 'community'),
    ...(input.tags ? { tags: input.tags } : {}),
  }
}

const branch = (id: string, name: string, summary: string): SeedBranch => ({ id, name, summary })

const subject = (id: string, name: string, summary: string, branchIds: string[], difficulty: Difficulty): SeedSubject => ({
  id,
  name,
  summary,
  branchIds,
  difficulty,
})

const concept = (id: string, name: string, summary: string, subjectId: string, difficulty: Difficulty): SeedConcept => ({
  id,
  name,
  summary,
  subjectId,
  difficulty,
})

const tool = (id: string, name: string, summary: string, openSource: boolean): SeedTool => ({ id, name, summary, openSource })

const language = (id: string, name: string, summary: string, difficulty: Difficulty): SeedLanguage => ({
  id,
  name,
  summary,
  difficulty,
})

interface AssessmentInput {
  skillId: string
  summary: string
  difficulty: Difficulty
  questions: Array<[prompt: string, options: string[], answerIndex: number]>
}

const assessment = (id: string, name: string, input: AssessmentInput): SeedAssessment => ({
  id,
  name,
  summary: input.summary,
  skillId: input.skillId,
  difficulty: input.difficulty,
  questions: input.questions.map(([prompt, options, answerIndex]) => ({ prompt, options, answerIndex })),
})

const module_ = (
  id: string,
  name: string,
  summary: string,
  description: string,
  skillIds: string[],
  hours: [number, number],
): SeedModule => ({
  id,
  name,
  summary,
  description,
  skillIds,
  estimatedHoursLow: hours[0],
  estimatedHoursHigh: hours[1],
})

/** Edge helpers keep the relationship section readable and reviewable. */
const requires = (from: string, to: string, weight?: number, note?: string): SeedEdge => ({
  from,
  to,
  type: 'REQUIRES',
  ...(weight !== undefined ? { weight } : {}),
  ...(note ? { note } : {}),
})
const usesTool = (from: string, to: string): SeedEdge => ({ from, to, type: 'USES' })
const usesSkill = (from: string, to: string): SeedEdge => ({ from, to, type: 'USES' })
const practisedBy = (skillId: string, projectId: string): SeedEdge => ({ from: skillId, to: projectId, type: 'PRACTICED_BY' })
const buildsSkill = (projectId: string, skillId: string): SeedEdge => ({ from: projectId, to: skillId, type: 'BUILDS_SKILL' })
const taughtBy = (entityId: string, resourceId: string): SeedEdge => ({ from: entityId, to: resourceId, type: 'TAUGHT_BY' })
const covers = (resourceId: string, entityId: string): SeedEdge => ({ from: resourceId, to: entityId, type: 'COVERS' })
const assumesSkill = (resourceId: string, skillId: string): SeedEdge => ({ from: resourceId, to: skillId, type: 'ASSUMES' })
const suggestsProject = (careerId: string, projectId: string): SeedEdge => ({ from: careerId, to: projectId, type: 'SUGGESTS_PROJECT' })
const teaches = (moduleId: string, skillId: string): SeedEdge => ({ from: moduleId, to: skillId, type: 'TEACHES' })
const assesses = (assessmentId: string, skillId: string): SeedEdge => ({ from: assessmentId, to: skillId, type: 'ASSESSES' })
const hasConcept = (subjectId: string, conceptId: string): SeedEdge => ({ from: subjectId, to: conceptId, type: 'HAS_CONCEPT' })
const buildsOn = (conceptId: string, baseConceptId: string): SeedEdge => ({ from: conceptId, to: baseConceptId, type: 'BUILDS_ON' })
const relatedTo = (a: string, b: string): SeedEdge => ({ from: a, to: b, type: 'RELATED_TO' })
const belongsTo = (entityId: string, branchId: string): SeedEdge => ({ from: entityId, to: branchId, type: 'BELONGS_TO' })

